begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,aud,role) select ('f1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'operations-'||n||'@example.test',now(),'authenticated','authenticated' from generate_series(1,4)n;
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status) select id,'Rental Test',email,'9999999999','https://linkedin.com/in/test','1990-01-01','approved' from auth.users where id::text like 'f1000000%';
insert into public.staff_roles(user_id,role) values('f1000000-0000-4000-8000-000000000001','admin'),('f1000000-0000-4000-8000-000000000004','membership_reviewer');
insert into public.resources(id,location_id,slug,name,kind,capacity,max_guests,max_duration_minutes,booking_horizon_days)
select ('f2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,l.id,'operations-fixture-'||n,'Rental fixture '||n,case when n=1 then 'workspace'::public.resource_kind else 'equipment'::public.resource_kind end,1,0,1440,10000 from generate_series(1,2)n cross join lateral(select id from public.locations limit 1)l;
insert into public.resource_booking_policies values('f2000000-0000-4000-8000-000000000001','workspace'),('f2000000-0000-4000-8000-000000000002','equipment');
insert into public.resource_hours(resource_id,day_of_week,opens_at,closes_at) select id,d,'09:00','17:00' from public.resources cross join generate_series(0,6)d where id::text like 'f2000000%';
delete from public.booking_inventory;
insert into public.booking_inventory values('f2000000-0000-4000-8000-000000000001','S01','GF','GF-10');
insert into public.inventory_locations(id,lab_location_id,code,name) select 'f3000000-0000-4000-8000-000000000001',id,'OPERATIONS-TEST','Rental test' from public.locations limit 1;
insert into public.asset_units(id,component_id,inventory_location_id,asset_tag) select 'f3000000-0000-4000-8000-000000000002',id,'f3000000-0000-4000-8000-000000000001','ARM-TEST-990004' from public.components limit 1;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('rental.unit',public.configure_equipment_rental_unit('f3000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000002',true,'Synthetic commissioning only')::text,true);
select set_config('rental.rate',public.approve_equipment_rental_rate(current_setting('rental.unit')::uuid,'hour',10000,now()-interval '1 day',null,0)::text,true);
select set_config('rental.dayrate',public.approve_equipment_rental_rate(current_setting('rental.unit')::uuid,'day',50000,now()-interval '1 day',null,0)::text,true);
select set_config('rental.notax',public.approve_equipment_rental_rate(current_setting('rental.unit')::uuid,'hour',10000,'2020-01-01','2021-01-01')::text,true);
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
update public.equipment_rental_settings set mock_payments_enabled=true;
update public.booking_policy_settings set mock_grants_enabled=true;
update public.booking_products set enabled=true,price_paise=50000;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.grant_mock_access('f1000000-0000-4000-8000-000000000002',(select id from public.booking_products where code='workspace-day'),'f2000000-0000-4000-8000-000000000001',array[date '2030-01-07',date '2030-01-08']);
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('ops.quote',public.create_equipment_rental_quote(current_setting('rental.dayrate')::uuid,null,null,array[date '2030-01-07',date '2030-01-08'])::text,true);
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.authorize_mock_equipment_payment(current_setting('ops.quote')::uuid);
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('ops.order',public.reserve_equipment_rental(current_setting('ops.quote')::uuid,null,'f2000000-0000-4000-8000-000000000001',(select id from public.booking_products where code='workspace-day'),array[date '2030-01-07',date '2030-01-08'])::text,true);
select set_config('ops.booking',(select booking_id::text from public.equipment_rental_orders where id=current_setting('ops.order')::uuid),true);
insert into public.kiosk_devices(id,location_id,name,public_key_jwk,key_thumbprint,status) select 'f4000000-0000-4000-8000-000000000001',id,'Synthetic daily equipment kiosk','{}','operations-test','active' from public.locations limit 1;
select ok(not has_function_privilege('authenticated','public.redeem_checkin_intent(text,uuid)','EXECUTE'),'member cannot redeem without verified kiosk edge');
select ok(not has_function_privilege('service_role','private.redeem_equipment_daily_intent(text,uuid,timestamptz)','EXECUTE'),'service cannot inject custom use time');
select ok(not has_function_privilege('authenticated','private.create_equipment_daily_intent(uuid,public.checkin_action,timestamptz)','EXECUTE'),'member cannot inject custom use time');
select lives_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-07 10:00+05:30')$$,'daily adapter accepts first use date');
select lives_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-08 10:00+05:30')$$,'daily adapter accepts second date without overnight entitlement');
select throws_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-08 07:00+05:30')$$,'22023','Daily equipment use is available only from 09:00 to 17:00','overnight storage does not grant morning use');
select throws_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-08 17:00+05:30')$$,'22023','Daily equipment use is available only from 09:00 to 17:00','17:00 closes equipment use');
select throws_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-09 10:00+05:30')$$,'22023','This date is not included in the daily rental','outside rental date denied');
select throws_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,'f1000000-0000-4000-8000-000000000003','2030-01-07 10:00+05:30')$$,'42501','Confirmed daily rental for this approved operator required','another member cannot use kit');
insert into public.certification_types(id,slug,name) values('f5000000-0000-4000-8000-000000000001','daily-kit-training','Daily kit training');
insert into public.resource_certification_requirements(resource_id,certification_type_id) values('f2000000-0000-4000-8000-000000000002','f5000000-0000-4000-8000-000000000001');
select throws_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-07 10:00+05:30')$$,'42501','Training must remain valid through today’s equipment use','missing training blocks use');
insert into public.member_certifications(member_id,certification_type_id,issued_by,expires_at) values(auth.uid(),'f5000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','2030-01-07 12:00+05:30');
select throws_ok($$select private.validate_equipment_daily_use(current_setting('ops.order')::uuid,auth.uid(),'2030-01-07 10:00+05:30')$$,'42501','Training must remain valid through today’s equipment use','training expiry before17 blocks daily use');
update public.member_certifications set expires_at='2031-01-01' where certification_type_id='f5000000-0000-4000-8000-000000000001';
insert into public.attendance_sessions(user_id,booking_id,resource_id,location_id,checked_in_by_device) select auth.uid(),o.workspace_booking_ids[1],'f2000000-0000-4000-8000-000000000001',r.location_id,'f4000000-0000-4000-8000-000000000001' from public.equipment_rental_orders o join public.resources r on r.id='f2000000-0000-4000-8000-000000000001' where o.id=current_setting('ops.order')::uuid;
select set_config('ops.intent',private.create_equipment_daily_intent(current_setting('ops.order')::uuid,'check_in','2030-01-07 10:00+05:30')::text,true);
select set_config('ops.hash',encode(extensions.digest(convert_to(current_setting('ops.intent')::jsonb->>'token','utf8'),'sha256'),'hex'),true);
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-07 10:01:01+05:30')$$,'22023','check-in token is expired, invalid, or already used','daily token expires after60seconds');
update public.kiosk_devices set status='revoked' where id='f4000000-0000-4000-8000-000000000001';
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-07 10:00:10+05:30')$$,'42501','kiosk device is not active','revoked kiosk cannot redeem');
update public.kiosk_devices set status='active' where id='f4000000-0000-4000-8000-000000000001';
insert into public.locations(id,slug,name) values('f4000000-0000-4000-8000-000000000009','other-equipment-test-lab','Other test lab');
insert into public.kiosk_devices(id,location_id,name,public_key_jwk,key_thumbprint,status) values('f4000000-0000-4000-8000-000000000002','f4000000-0000-4000-8000-000000000009','Other lab kiosk','{}','other-equipment-kiosk','active');
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000002','2030-01-07 10:00:10+05:30')$$,'42501','booking belongs to another location','other lab kiosk cannot redeem');
select lives_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-07 10:00:10+05:30')$$,'verified kiosk redeems first day token');
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-07 10:00:11+05:30')$$,'22023','check-in token is expired, invalid, or already used','token cannot be reused');
select is((select count(*)::integer from public.attendance_sessions where user_id=auth.uid()),1,'equipment use preserves the existing building attendance session');
select set_config('ops.out',private.create_equipment_daily_intent(current_setting('ops.order')::uuid,'check_out','2030-01-07 10:30+05:30')::text,true);
select lives_ok($$select private.redeem_equipment_daily_intent(encode(extensions.digest(convert_to(current_setting('ops.out')::jsonb->>'token','utf8'),'sha256'),'hex'),'f4000000-0000-4000-8000-000000000001','2030-01-07 10:30:10+05:30')$$,'kit return closes equipment use');
select is((select status::text from public.attendance_sessions where user_id=auth.uid()),'active','kit return does not check member out of building');
select set_config('ops.reentry',private.create_equipment_daily_intent(current_setting('ops.order')::uuid,'check_in','2030-01-07 11:00+05:30')::text,true);
select lives_ok($$select private.redeem_equipment_daily_intent(encode(extensions.digest(convert_to(current_setting('ops.reentry')::jsonb->>'token','utf8'),'sha256'),'hex'),'f4000000-0000-4000-8000-000000000001','2030-01-07 11:00:10+05:30')$$,'same-day reentry permitted after return');
select set_config('ops.laterout',private.create_equipment_daily_intent(current_setting('ops.order')::uuid,'check_out','2030-01-07 18:00+05:30')::text,true);
select lives_ok($$select private.redeem_equipment_daily_intent(encode(extensions.digest(convert_to(current_setting('ops.laterout')::jsonb->>'token','utf8'),'sha256'),'hex'),'f4000000-0000-4000-8000-000000000001','2030-01-07 18:00:10+05:30')$$,'after-hours return remains possible without granting use');
select set_config('ops.intent',private.create_equipment_daily_intent(current_setting('ops.order')::uuid,'check_in','2030-01-08 10:00+05:30')::text,true);
select set_config('ops.hash',encode(extensions.digest(convert_to(current_setting('ops.intent')::jsonb->>'token','utf8'),'sha256'),'hex'),true);
update public.basic_onboarding_applications set status='revoked' where user_id=auth.uid();
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-08 10:00:10+05:30')$$,'42501','Confirmed daily rental for this approved operator required','revocation between intent and kiosk blocks use');
update public.basic_onboarding_applications set status='approved' where user_id=auth.uid();
insert into public.booking_closures(location_id,closed_on,reason) select location_id,'2030-01-08','Synthetic closure' from public.resources where id='f2000000-0000-4000-8000-000000000002';
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-08 10:00:10+05:30')$$,'42501','Equipment use is closed for this date','new closure rechecked at kiosk');
delete from public.booking_closures where closed_on='2030-01-08';
update public.paid_access_entitlements set revoked_at=now() where user_id=auth.uid() and resource_id='f2000000-0000-4000-8000-000000000001';
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-08 10:00:10+05:30')$$,'42501','Current paid workspace must cover this use date','workspace entitlement revocation rechecked');
update public.paid_access_entitlements set revoked_at=null where user_id=auth.uid();
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.admin_list_equipment_operations()$$,'42501','Website Admin required','membership Staff cannot inspect operational inventory');
select throws_ok($$select public.admin_update_equipment_unit(current_setting('rental.unit')::uuid,'f3000000-0000-4000-8000-000000000001','[]',true,'Unauthorized maintenance')$$,'42501','Website Admin required','Staff cannot maintain equipment');
set local role authenticated;
with changed as (update public.asset_units set condition_note='Unapproved Staff edit' where id='f3000000-0000-4000-8000-000000000002' returning id) select is((select count(*)::integer from changed),0,'membership Staff cannot directly modify mapped asset');
reset role;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(public.admin_list_equipment_operations()->'units'),1,'Admin lists commissioned unit');
set local role authenticated;
with changed as (update public.asset_units set condition_note='Unaudited Admin edit' where id='f3000000-0000-4000-8000-000000000002' returning id) select is((select count(*)::integer from changed),0,'Admin mapped asset writes require audited operations RPC');
select lives_ok($$select public.admin_update_equipment_unit(current_setting('rental.unit')::uuid,'f3000000-0000-4000-8000-000000000001','[]',false,'Authenticated Admin operation')$$,'authenticated Admin can use operational RPC');
reset role;
select lives_ok($$select public.admin_update_equipment_unit(current_setting('rental.unit')::uuid,'f3000000-0000-4000-8000-000000000001','[{"name":"Power supply","quantity":1}]',true,'Synthetic maintenance')$$,'Admin stores kit and enters maintenance');
select throws_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-08 10:00:10+05:30')$$,'42501','Equipment is not operational','maintenance blocks kiosk use');
select public.admin_update_equipment_unit(current_setting('rental.unit')::uuid,'f3000000-0000-4000-8000-000000000001','[{"name":"Power supply","quantity":1}]',false,'Repair completed');
select is((select commissioned from public.equipment_rental_units where id=current_setting('rental.unit')::uuid),false,'maintenance exit requires explicit recommission');
select public.configure_equipment_rental_unit('f3000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000002',true,'Checked and recommissioned');
select throws_ok($$select public.admin_update_equipment_unit(current_setting('rental.unit')::uuid,'f3000000-0000-4000-8000-000000000001','[{"name":"Cable","quantity":0}]',false,'Bad kit')$$,'22023','Each kit entry requires name and positive integer quantity only','invalid kit quantity rejected');
select lives_ok($$select public.admin_replace_equipment_rate(current_setting('rental.rate')::uuid,12000,0,'2030-01-01',null,'Approved future hourly revision')$$,'Admin replaces rate at explicit nonoverlapping boundary');
select throws_ok($$select public.admin_replace_equipment_rate(current_setting('rental.rate')::uuid,11000,0,'2030-01-01',null,'Stale admin view')$$,'22023','Current rate version, future boundary and reason required','stale replacement rejected');
select is((select count(*)::integer from public.audit_events where action='equipment.operations_updated'),3,'operations changes audited');
select lives_ok($$select private.redeem_equipment_daily_intent(current_setting('ops.hash'),'f4000000-0000-4000-8000-000000000001','2030-01-08 10:00:10+05:30')$$,'second day can begin after yesterday return');
select is((select count(distinct use_date)::integer from public.equipment_daily_sessions),2,'daily records distinguish two use dates');
select * from finish();
rollback;
